package dev.mineagent.runtime.core.agent;
import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import javax.imageio.ImageIO;import java.io.*;import java.awt.image.BufferedImage;import static org.junit.jupiter.api.Assertions.*;
class SkinImageTest {
 @Test void paintsNamedUvPartsAndEditingKeepsOtherPixels()throws Exception{var json=new ObjectMapper();byte[] first=SkinImage.paint(null,"wide",json.readTree("{\"base_color\":\"#112233\",\"rects\":[{\"part\":\"head.front\",\"color\":\"#ff0000\"}]}"));var a=ImageIO.read(new ByteArrayInputStream(first));assertEquals(64,a.getWidth());assertEquals(0xffff0000,a.getRGB(8,8));assertEquals(0xff112233,a.getRGB(20,20));assertEquals(0,a.getRGB(40,8)>>>24);byte[] edited=SkinImage.paint(first,"wide",json.readTree("{\"rects\":[{\"part\":\"head.front\",\"x\":1,\"y\":2,\"width\":2,\"height\":1,\"color\":\"#00ff00\"}]}"));var b=ImageIO.read(new ByteArrayInputStream(edited));assertEquals(0xff00ff00,b.getRGB(9,10));assertEquals(a.getRGB(20,20),b.getRGB(20,20));}
 @Test void acceptsClassicAndRejectsInvalidDimensions()throws Exception{var input=new BufferedImage(64,32,BufferedImage.TYPE_INT_ARGB);input.setRGB(4,20,0xffabcdef);var out=new ByteArrayOutputStream();ImageIO.write(input,"PNG",out);var fixed=ImageIO.read(new ByteArrayInputStream(SkinImage.normalize(out.toByteArray())));assertEquals(64,fixed.getHeight());assertEquals(0xffabcdef,fixed.getRGB(23,52));var bad=new BufferedImage(128,128,BufferedImage.TYPE_INT_ARGB);out.reset();ImageIO.write(bad,"PNG",out);assertThrows(IOException.class,()->SkinImage.normalize(out.toByteArray()));}
 @Test void slimUvAndBadPaintStayBounded()throws Exception{assertEquals(3,SkinImage.regions("slim").get("right_arm.front").width());var json=new ObjectMapper();assertThrows(IllegalArgumentException.class,()->SkinImage.paint(null,"wide",json.readTree("{\"rects\":[{\"part\":\"head.front\",\"x\":7,\"width\":5,\"color\":\"#000000\"}]}")));}
}
